// Reads the configurable discovery window to support daily or weekly cadence without changing this formula.
const sourceSettings = $('02 · Source Catalogue').first().json;
const configuredDiscoveryHours = Number(sourceSettings.discoveryLookbackHours);
const DISCOVERY_LOOKBACK_HOURS = Number.isFinite(configuredDiscoveryHours)
  && configuredDiscoveryHours >= 72
  && configuredDiscoveryHours <= 720
  ? configuredDiscoveryHours
  : 168;
const FUTURE_TOLERANCE_HOURS = 6;
const nowMs = Date.now();

// Decodes HTML entities, including the numeric entities seen in The Verge URLs.
const decodeEntities = (value) => String(value ?? '')
  .replace(/&amp;/gi, '&')
  .replace(/&quot;/gi, '"')
  .replace(/&#39;|&apos;/gi, "'")
  .replace(/&#(\d+);/g, (_, code) => String.fromCodePoint(Number(code)))
  .replace(/&#x([0-9a-f]+);/gi, (_, code) => String.fromCodePoint(parseInt(code, 16)))
  .replace(/&lt;/gi, '<')
  .replace(/&gt;/gi, '>');

// Removes tags and repeated whitespace to deliver compact text to the next nodes.
const cleanText = (value) => decodeEntities(value)
  .replace(/<[^>]*>/g, ' ')
  .replace(/\s+/g, ' ')
  .trim();

// Accepts only HTTP/HTTPS image URLs provided by the feed.
const normalizeImageUrl = (value) => {
  const url = decodeEntities(value).trim();
  return /^https?:\/\/[^\s"'<>]+$/i.test(url) ? url : null;
};

// Reads the URL from the real shapes emitted by enclosure and Media RSS fields.
const readMediaUrl = (value) => {
  const entry = Array.isArray(value) ? value[0] : value;
  if (!entry) return null;
  if (typeof entry === 'string') return normalizeImageUrl(entry);
  return normalizeImageUrl(entry.url || entry.$?.url || entry.href || entry.$?.href);
};

// Looks for an image in the proven order and uses HTML only as a feed-provided fallback.
const extractImageUrl = (input) => {
  const directCandidates = [
    input.enclosure,
    input['media:content'],
    input['media:thumbnail'],
  ];
  for (const candidate of directCandidates) {
    const imageUrl = readMediaUrl(candidate);
    if (imageUrl) return imageUrl;
  }

  const html = String(input['content:encoded'] || input.content || '');
  const match = html.match(/<img\b[^>]*\bsrc\s*=\s*(["'])(.*?)\1/i);
  return normalizeImageUrl(match?.[2]);
};

// Standardizes the URL so equivalent links share the same key in the dedupe.
const canonicalizeUrl = (value) => {
  // Rejects empty values or anything that is not an HTTP/HTTPS link.
  const raw = decodeEntities(value).trim();
  if (!/^https?:\/\/\S+$/i.test(raw)) return '';

  // Removes fragments and splits the main part from the URL parameters.
  const withoutHash = raw.split('#')[0];
  const queryIndex = withoutHash.indexOf('?');
  let base = queryIndex >= 0 ? withoutHash.slice(0, queryIndex) : withoutHash;
  const query = queryIndex >= 0 ? withoutHash.slice(queryIndex + 1) : '';

  // Lists known parameters that serve only for tracking.
  const trackingKeys = new Set([
    'fbclid', 'gclid', 'dclid', 'msclkid', 'mc_cid', 'mc_eid',
  ]);

  // Preserves functional parameters and drops only tracking parameters.
  const keptParams = query
    .split('&')
    .filter(Boolean)
    .filter((part) => {
      const key = part.split('=')[0].toLowerCase();
      return !key.startsWith('utm_') && !trackingKeys.has(key);
    });

  // Confirms the base is still valid and removes unnecessary trailing slashes.
  if (!/^https?:\/\/[^\s/]+/i.test(base)) return '';
  base = base.replace(/\/+$/, '');

  return keptParams.length ? `${base}?${keptParams.join('&')}` : base;
};

// Converts categories to text without serializing objects as "[object Object]".
const cleanCategory = (value) => {
  if (value && typeof value === 'object') {
    return cleanText(value._ || value.name || value.$?.term || '');
  }
  return cleanText(value);
};

// Processes every article and returns the same contract for any source.
return $input.all().map((item, index) => {
  const input = item.json ?? {};

  // Picks and cleans the essential article identification fields.
  const title = cleanText(input.title);
  const canonicalUrl = canonicalizeUrl(input.link || input.guid);

  // Uses proven date fallbacks and computes the article age in hours.
  const rawDate = input.isoDate || input.pubDate || input.published || input.date;
  const timestamp = rawDate ? Date.parse(rawDate) : NaN;
  const hasValidDate = Number.isFinite(timestamp);
  const ageHours = hasValidDate ? (nowMs - timestamp) / 3600000 : null;
  const publishedAt = hasValidDate ? new Date(timestamp).toISOString() : null;

  // Cleans author and summary, limiting the text that will go to the AI.
  const author = cleanText(input.creator || input['dc:creator'] || input.author);
  const snippet = cleanText(
    input.contentSnippet || input.summary || input.description || input.content,
  ).slice(0, 600);

  // Preserves only textual categories and drops empty feed objects.
  const categories = Array.isArray(input.categories)
    ? input.categories.map(cleanCategory).filter(Boolean)
    : [];

  // Extracts the image without asking the AI to copy or transform the URL.
  const imageUrl = extractImageUrl(input);

  // Confirms the required fields and flags whether the article is complete and current.
  const sourceId = cleanText(input.sourceId);
  const sourceName = cleanText(input.sourceName);
  const isComplete = Boolean(title && canonicalUrl && publishedAt && sourceId && sourceName);
  const isFresh = Boolean(
    hasValidDate
    && ageHours >= -FUTURE_TOLERANCE_HOURS
    && ageHours <= DISCOVERY_LOOKBACK_HOURS
  );

  // Records objective reasons for auditing when an article is blocked.
  const validationIssues = [];
  if (!title) validationIssues.push('missing_title');
  if (!canonicalUrl) validationIssues.push('missing_or_invalid_url');
  if (!publishedAt) validationIssues.push('missing_or_invalid_date');
  if (!sourceId || !sourceName) validationIssues.push('missing_source_metadata');
  if (publishedAt && !isFresh) validationIssues.push('outside_discovery_window');

  // Returns only the normalized contract and preserves the link to the input item.
  return {
    json: {
      sourceId,
      sourceName,
      sourceCountry: cleanText(input.sourceCountry),
      sourceLanguage: cleanText(input.sourceLanguage),
      sourceRole: cleanText(input.sourceRole),
      sourcePriority: Number(input.sourcePriority) || 999,
      title,
      canonicalUrl,
      publishedAt,
      author,
      snippet,
      categories,
      imageUrl,
      ageHours: ageHours === null ? null : Math.round(ageHours * 10) / 10,
      isComplete,
      isFresh,
      validationIssues,
    },
    pairedItem: { item: index },
  };
});

// Reads the real settings to separate the discovery window from the recency point decay.
const settings = $('02 · Source Catalogue').first().json;
const configuredDecayHours = Number(settings.freshnessDecayHours);
const FRESHNESS_DECAY_HOURS = Number.isFinite(configuredDecayHours) && configuredDecayHours >= 24 && configuredDecayHours <= 720 ? configuredDecayHours : 48;
const inputItems = $input.all();
const TARGET_BATCH_SIZE = 30;
const MAX_SOURCE_SHARE = 0.4;
const MAX_PER_SOURCE = Math.ceil(TARGET_BATCH_SIZE * MAX_SOURCE_SHARE);

// Keeps any computed value within the valid range between zero and one.
const clamp01 = (value) => Math.min(1, Math.max(0, value));

// Counts explicit, auditable editorial signals without asking this step for a semantic decision.
const countMatches = (text, patterns) => patterns.reduce((total, pattern) => total + (pattern.test(text) ? 1 : 0), 0);
const releasePatterns = [/\bintroduc(?:e|es|ed|ing)\b/i,/\blaunch(?:es|ed|ing)?\b/i,/\breleas(?:e|es|ed|ing)\b/i,/\b(?:now |generally )?available\b/i,/\bopen[- ]sourc(?:e|es|ed|ing)\b/i,/\b(?:now has|gets its own|new capability)\b/i];
const operationalPatterns = [/\bapi\b/i,/\bagent(?:s|ic)?\b/i,/\bautomat(?:e|es|ed|ion|ions|ing)\b/i,/\bworkflow(?:s)?\b/i,/\b(?:coding|developer|document|spreadsheet|presentation|video|transcri(?:be|ption))\b/i,/\b(?:browser|desktop app|cowork|build|control)\b/i];
const specificityPatterns = [/\b\d+(?:\.\d+)?[mbk]?\b/i,/\bbenchmark(?:s)?\b/i,/\b(?:price|pricing|cost|free)\b/i,/\b(?:context window|tokens?|parameters?)\b/i];

// Assigns authority by the source's editorial role, without demoting new official sources by catalogue order.
const authorityByRole = {'primary-lab':1,'primary-company':1,'automation-primary':1,'open-source':0.9,'research-context':0.9,'builder-curation':0.8,'enterprise-context':0.8,'market-context':0.75,'independent-context':0.75};

// Computes five separate signals so the AI receives score and evidence, not an opaque decision.
const scored = inputItems.map((item, inputIndex) => {
  const article=item.json??{}; const ageHours=Number(article.ageHours); const sourceRole=String(article.sourceRole||'');
  const evidence=[article.title,article.snippet,article.evidenceText].filter(Boolean).join(' ').slice(0,6000);
  const freshnessRatio=Number.isFinite(ageHours)?clamp01(1-Math.max(0,ageHours)/FRESHNESS_DECAY_HOURS):0;
  const freshnessPoints=20*freshnessRatio; const sourceAuthorityPoints=15*(authorityByRole[sourceRole]??0.65);
  const releaseImportancePoints=Math.min(30,countMatches(evidence,releasePatterns)*6);
  const operationalImpactPoints=Math.min(25,countMatches(evidence,operationalPatterns)*5);
  const specificityPoints=Math.min(10,countMatches(evidence,specificityPatterns)*2.5);
  const technicalScore=Math.round((freshnessPoints+sourceAuthorityPoints+releaseImportancePoints+operationalImpactPoints+specificityPoints)*100)/100;
  return {item,inputIndex,sourceKey:String(article.sourceId||article.sourceName||'unknown-source'),publishedMs:Date.parse(article.publishedAt||'')||0,titleKey:String(article.title||''),technicalScore,freshnessPoints:Math.round(freshnessPoints*100)/100,sourceAuthorityPoints:Math.round(sourceAuthorityPoints*100)/100,releaseImportancePoints,operationalImpactPoints,specificityPoints};
});

// Sorts by score and uses date, catalogue priority, and title only for stable tie-breaking.
const compareCandidates=(left,right)=>right.technicalScore-left.technicalScore||right.publishedMs-left.publishedMs||Number(left.item.json.sourcePriority??999)-Number(right.item.json.sourcePriority??999)||left.titleKey.localeCompare(right.titleKey);
scored.sort(compareCandidates);

// Groups candidates by source to reserve diversity before completing the batch.
const bySource=new Map();
for(const candidate of scored){if(!bySource.has(candidate.sourceKey))bySource.set(candidate.sourceKey,[]);bySource.get(candidate.sourceKey).push(candidate);}

// Reserves the best article from each source, starting with the source whose best item has the highest score.
const selected=[];const selectedIndexes=new Set();const sourceCounts=new Map();
const sourceQueues=[...bySource.values()].sort((left,right)=>compareCandidates(left[0],right[0]));
for(const queue of sourceQueues){if(selected.length>=TARGET_BATCH_SIZE)break;const candidate=queue[0];selected.push(candidate);selectedIndexes.add(candidate.inputIndex);sourceCounts.set(candidate.sourceKey,1);}

// Fills the batch by score while avoiding excessive dominance by a single source.
for(const candidate of scored){if(selected.length>=TARGET_BATCH_SIZE)break;if(selectedIndexes.has(candidate.inputIndex))continue;const currentCount=sourceCounts.get(candidate.sourceKey)??0;if(currentCount>=MAX_PER_SOURCE)continue;selected.push(candidate);selectedIndexes.add(candidate.inputIndex);sourceCounts.set(candidate.sourceKey,currentCount+1);}

// Relaxes the per-source limit only if needed to complete the batch.
for(const candidate of scored){if(selected.length>=TARGET_BATCH_SIZE)break;if(selectedIndexes.has(candidate.inputIndex))continue;selected.push(candidate);selectedIndexes.add(candidate.inputIndex);}

// Keeps the surplus after the batch because the final cut belongs to node 12.
const ranked=[...selected,...scored.filter((candidate)=>!selectedIndexes.has(candidate.inputIndex))];

// Returns the articles with auditable signals and the correct link to the input.
return ranked.map((candidate,index)=>({json:{...candidate.item.json,candidateId:'C'+String(index+1).padStart(2,'0'),technicalScore:candidate.technicalScore,freshnessPoints:candidate.freshnessPoints,sourceAuthorityPoints:candidate.sourceAuthorityPoints,releaseImportancePoints:candidate.releaseImportancePoints,operationalImpactPoints:candidate.operationalImpactPoints,specificityPoints:candidate.specificityPoints,balancedRank:index+1},pairedItem:{item:candidate.inputIndex}}));

// Reads the parser output, real candidate batch, and user preferences needed for validation.
const input = $input.first().json;
const originalCandidates = $('14 · Aggregate Candidate Batch').first().json.candidates ?? [];
const userSettings = $('02 · Source Catalogue').first().json;
const outputLanguage = String(userSettings.outputLanguage ?? 'English').trim() || 'English';
const configuredStoriesPerDigest = Number(userSettings.storiesPerDigest);
const storiesPerDigestIsValid = Number.isInteger(configuredStoriesPerDigest)
  && configuredStoriesPerDigest >= 1
  && configuredStoriesPerDigest <= 10;
const storiesPerDigest = storiesPerDigestIsValid ? configuredStoriesPerDigest : 5;
const curationPoolSize = Math.min(10, storiesPerDigest + 5);
const candidateById = new Map(
  originalCandidates.map((candidate) => [candidate.candidateId, candidate]),
);

// Maps the supported output languages to all fixed newsletter copy so branding follows the preference.
const newsletterCopy = {
  English: {
    title: 'AI Insight Weekly',
    tagline: 'Get smarter about AI in 5 minutes, every week.',
    greeting: 'Hello!',
    welcome: '5 stories · 5 min read · what changed in AI this week.',
    whatsInsideLabel: 'This week:',
    editorialHeading: '☕ Good morning, everyone!',
    editionLabel: "This week's edition",
    credibility: 'Every story was checked against its source, publication date, and stated availability.',
    impactLabel: 'How this affects you',
    limitationLabel: 'Limitation / watch-out',
    hackLabel: 'Quick hack',
    sourceLabel: 'Read the complete story at',
  },
  Português: {
    title: 'Insight Semanal de IA',
    tagline: 'Fica mais inteligente em IA em 5 minutos, toda semana.',
    greeting: 'Olá!',
    welcome: '5 histórias · 5 min de leitura · o que muda em IA esta semana.',
    whatsInsideLabel: 'Esta semana:',
    editorialHeading: '☕ Bom dia, pessoal!',
    editionLabel: 'A edição desta semana',
    credibility: 'Todas as histórias foram verificadas pela fonte, data de publicação e disponibilidade informada.',
    impactLabel: 'Como isso afeta você',
    limitationLabel: 'Limitação / atenção',
    hackLabel: 'Hack rápido',
    sourceLabel: 'Leia a matéria completa em',
  },
};
const languageKey = /^portugu/i.test(outputLanguage) || /^pt(?:[-_ ]|$)/i.test(outputLanguage)
  ? 'Português'
  : 'English';
const copy = newsletterCopy[languageKey];

// Normalizes the AI payload without silently accepting free text or malformed JSON.
let curated = input.output ?? input.text ?? input;
if (typeof curated === 'string') {
  try {
    curated = JSON.parse(curated);
  } catch {
    curated = {};
  }
}

// Validates the semantic contract that JSON Schema alone cannot prove.
// Two tiers: hard errors (integrity/trust) block the whole digest; quality shortfalls only
// DROP the individual story, letting the ranked shortlist buffer backfill the edition.
const issues = [];
const droppedStories = [];
const fidelityNotes = [];
if (!storiesPerDigestIsValid) {
  issues.push('storiesPerDigest must be an integer from 1 to 10');
}
if (String(curated.outputLanguage ?? '').trim() !== outputLanguage) {
  issues.push('outputLanguage does not match the configured preference');
}
const requestedStories = Array.isArray(curated.stories) ? curated.stories : [];
if (requestedStories.length < storiesPerDigest || requestedStories.length > curationPoolSize) {
  issues.push(`stories must contain between ${storiesPerDigest} and ${curationPoolSize} ranked shortlist items`);
}
const countWords = (value) => String(value ?? '').trim().split(/\s+/).filter(Boolean).length;
const seenIds = new Set();
const stories = [];
for (const selected of requestedStories) {
  const candidate = candidateById.get(selected.candidateId);
  // Integrity failures mean the AI output cannot be trusted: block the whole digest.
  if (!candidate) {
    issues.push(`unknown candidateId: ${selected.candidateId ?? '(missing)'}`);
    continue;
  }
  if (seenIds.has(selected.candidateId)) {
    issues.push(`duplicate candidateId: ${selected.candidateId}`);
    continue;
  }
  seenIds.add(selected.candidateId);
  // The AI sometimes rewrites the source name or canonical URL. The trusted candidate values are
  // used downstream regardless, so a mismatch is recorded as a note — never a reason to drop a
  // valid, on-topic story (that spurious drop blocked execution 3598).
  const fidelityMismatch = [];
  if (selected.sourceName !== candidate.sourceName) fidelityMismatch.push('sourceName');
  if (selected.canonicalUrl !== candidate.canonicalUrl) fidelityMismatch.push('canonicalUrl');
  if (fidelityMismatch.length) fidelityNotes.push({ candidateId: selected.candidateId, fields: fidelityMismatch });
  // Quality shortfalls drop only THIS story; a single weak item never blocks a full edition.
  const displayTitle = String(selected.displayTitle ?? '').trim();
  const editorialFields = ['summary', 'context', 'whyItMatters', 'limitation', 'quickAction', 'quickHack'];
  const combinedLeadWords = countWords(selected.summary) + countWords(selected.context);
  const evidenceChars = Number(candidate.evidenceLength ?? String(candidate.evidenceText ?? '').length);
  let dropReason = null;
  if (!displayTitle) dropReason = 'empty displayTitle';
  else if (editorialFields.some((field) => !String(selected[field] ?? '').trim())) dropReason = 'empty editorial text';
  else if (combinedLeadWords < 60) dropReason = `combined news lead too short (${combinedLeadWords} words)`;
  else if (evidenceChars < 700) dropReason = 'insufficient source evidence for expanded coverage';
  if (dropReason) {
    droppedStories.push({ candidateId: selected.candidateId, reason: dropReason });
    continue;
  }
  stories.push({
    candidateId: candidate.candidateId,
    title: candidate.title,
    displayTitle,
    sourceId: candidate.sourceId,
    sourceName: candidate.sourceName,
    canonicalUrl: candidate.canonicalUrl,
    publishedAt: candidate.publishedAt,
    imageUrl: candidate.imageUrl || null,
    summary: String(selected.summary ?? '').trim(),
    context: String(selected.context ?? '').trim(),
    whyItMatters: String(selected.whyItMatters ?? '').trim(),
    limitation: String(selected.limitation ?? '').trim(),
    quickAction: String(selected.quickAction ?? '').trim(),
    quickHack: String(selected.quickHack ?? '').trim(),
  });
}

// Validates digest-level editorial fields before any delivery object can pass the safety gate.
const digestTitle = String(curated.digestTitle ?? '').trim();
const overview = String(curated.overview ?? '').trim();
const intro = String(curated.intro ?? '').trim();
if (!digestTitle) issues.push('digestTitle is empty');
if (!overview) issues.push('overview is empty');
if (!intro) issues.push('intro is empty');

// Escapes every dynamic value before building the isolated HTML preview.
const escapeHtml = (value) => String(value ?? '')
  .replace(/&/g, '&amp;')
  .replace(/</g, '&lt;')
  .replace(/>/g, '&gt;')
  .replace(/"/g, '&quot;')
  .replace(/'/g, '&#39;');

// Builds each preview card with the expanded editorial context, impact, caveat, hack, and source.
const storyHtml = stories.map((story, index) => {
  const imageHtml = story.imageUrl
    ? `<tr><td style="padding:0 0 20px 0;"><a href="${escapeHtml(story.canonicalUrl)}" style="text-decoration:none;"><img src="${escapeHtml(story.imageUrl)}" alt="${escapeHtml(story.displayTitle)}" width="576" style="display:block;width:100%;max-width:576px;height:auto;border:0;border-radius:10px;"></a></td></tr>`
    : '';
  return `<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="width:100%;border-collapse:separate;border-spacing:0;border:1px solid #111827;border-radius:12px;background:#ffffff;"><tr><td style="padding:22px 22px 14px 22px;"><div style="font-size:12px;font-weight:700;letter-spacing:0.08em;text-transform:uppercase;color:#2563eb;">${String(index + 1).padStart(2, '0')}</div><h2 style="margin:8px 0 0 0;font-size:21px;line-height:1.3;color:#111827;">${escapeHtml(story.displayTitle)}</h2></td></tr><tr><td style="padding:0 22px;">${imageHtml ? `<table role="presentation" width="100%" cellpadding="0" cellspacing="0">${imageHtml}</table>` : ''}</td></tr><tr><td style="padding:0 22px 22px 22px;font-size:15px;line-height:1.65;color:#334155;"><p style="margin:0 0 16px 0;">${escapeHtml(story.summary)}</p><p style="margin:0 0 18px 0;">${escapeHtml(story.context)}</p><table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="width:100%;background:#f2f7ff;border-left:5px solid #2563eb;border-radius:8px;"><tr><td style="padding:14px 16px;font-size:14px;line-height:1.55;color:#0f2c4d;"><strong>${escapeHtml(copy.impactLabel)}:</strong> ${escapeHtml(story.whyItMatters)}</td></tr></table><p style="margin:14px 0 0 0;padding:12px 14px;background:#fff7ed;border-radius:8px;font-size:14px;line-height:1.55;color:#7c2d12;"><strong>${escapeHtml(copy.limitationLabel)}:</strong> ${escapeHtml(story.limitation)}</p><p style="margin:10px 0 0 0;padding:12px 14px;background:#ecfdf5;border-radius:8px;font-size:14px;line-height:1.55;color:#065f46;"><strong>${escapeHtml(copy.hackLabel)}:</strong> ${escapeHtml(story.quickHack)}</p><p style="margin:18px 0 0 0;font-size:13px;"><a href="${escapeHtml(story.canonicalUrl)}" style="color:#2563eb;text-decoration:underline;font-weight:700;">${escapeHtml(copy.sourceLabel)} ${escapeHtml(story.sourceName)} →</a></p></td></tr></table><table role="presentation" width="100%" cellpadding="0" cellspacing="0"><tr><td height="28" style="height:28px;line-height:28px;font-size:1px;">&nbsp;</td></tr></table>`;
}).join('');

// The digest ships only when enough quality stories survived every integrity and depth check.
if (stories.length < storiesPerDigest) {
  issues.push(`only ${stories.length} quality stories survived the depth/evidence gate; need ${storiesPerDigest}`);
}
// Builds one localized preview and subject only when every structural and semantic check passes.
const canSend = issues.length === 0 && stories.length >= storiesPerDigest;
const digestDate = new Date().toISOString().slice(0, 10);
const emailSubject = canSend ? `${copy.title} | ${digestTitle} | ${digestDate}` : '';
const whatsInsideBody = stories.slice(0, 3).map((s) => s.displayTitle).join(' · ');
const preheaderText = whatsInsideBody;
const emailHtml = canSend
  ? `<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"></head><body style="margin:0;padding:0;background:#ffffff;font-family:Arial,sans-serif;color:#0f172a;"><div style="display:none;max-height:0;overflow:hidden;mso-hide:all;">${escapeHtml(preheaderText)}</div><div style="display:none;max-height:0;overflow:hidden;">&#8199;&#65279;&#8199;&#65279;&#8199;&#65279;&#8199;&#65279;&#8199;&#65279;&#8199;&#65279;&#8199;&#65279;&#8199;&#65279;</div><table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="width:100%;background:#ffffff;"><tr><td align="center" style="padding:20px 12px;"><table role="presentation" width="640" cellpadding="0" cellspacing="0" style="width:100%;max-width:640px;border-collapse:separate;border-spacing:0;"><tr><td align="center" style="padding:18px 28px;background:#1e1b4b;background:linear-gradient(135deg,#1e1b4b,#2563eb);color:#ffffff;border-radius:12px;"><h1 style="margin:0;font-size:22px;line-height:1.2;color:#ffffff;">${escapeHtml(copy.title)}</h1><p style="margin:4px 0 0 0;font-size:12px;line-height:1.4;color:#c7d2fe;">${escapeHtml(copy.tagline)}</p></td></tr><tr><td height="40" style="height:40px;line-height:40px;font-size:1px;">&nbsp;</td></tr><tr><td><table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="width:100%;border:1px solid #e2e8f0;border-radius:10px;background:#f8fafc;"><tr><td style="padding:12px 16px;font-size:14px;line-height:1.5;color:#334155;"><strong style="color:#2563eb;">${escapeHtml(copy.whatsInsideLabel)}</strong> ${escapeHtml(whatsInsideBody)}</td></tr></table></td></tr><tr><td height="28" style="height:28px;line-height:28px;font-size:1px;">&nbsp;</td></tr><tr><td><h2 style="margin:0 0 14px 0;font-size:20px;line-height:1.35;color:#111827;">${escapeHtml(copy.editorialHeading)}</h2><p style="margin:0 0 12px 0;font-size:16px;line-height:1.65;color:#334155;">${escapeHtml(intro)}</p><p style="margin:0;font-size:12px;line-height:1.5;color:#64748b;">${escapeHtml(copy.credibility)}</p></td></tr><tr><td height="44" style="height:44px;line-height:44px;font-size:1px;">&nbsp;</td></tr><tr><td>${storyHtml}</td></tr><tr><td style="padding:18px 28px;background:#e2e8f0;border-radius:12px;font-size:12px;line-height:1.5;color:#64748b;">${escapeHtml(copy.title)} · ${escapeHtml(digestTitle)} · ${digestDate}</td></tr></table></td></tr></table></body></html>`
  : '';

// Returns one delivery object plus the stable records needed by the post-send audit path.
return [{
  json: {
    canSend,
    validationIssues: issues,
    outputLanguage,
    storiesPerDigest,
    curationPoolSize,
