// Junta as N historias (uma por chamada, saida em texto tolerante) num objeto de digest,
// no MESMO formato que o parser antigo entregava. O n8n conta; o modelo nunca decide a quantidade.
function parseLenient(raw){ if(raw&&typeof raw==='object')return raw; let s=String(raw??'').trim();
  const f=s.match(/```(?:json)?\s*([\s\S]*?)```/i); if(f)s=f[1].trim();
  if(!s.startsWith('{')){const a=s.indexOf('{'),b=s.lastIndexOf('}'); if(a>=0&&b>a)s=s.slice(a,b+1);}
  try{return JSON.parse(s);}catch(e){return null;} }
const gen = $input.all();
const src = $('15.2 · Split Selection to Stories').all();
const framing = src[0]?.json?.__framing ?? {};
const stories = [];
for (let i = 0; i < src.length; i++) {
  const c = src[i].json;
  const e = parseLenient(gen[i]?.json?.text ?? gen[i]?.json?.output) ?? {};
  stories.push({ candidateId: c.candidateId, title: c.title, displayTitle: c.displayTitle,
    sourceId: c.sourceId, sourceName: c.sourceName, canonicalUrl: c.canonicalUrl,
    publishedAt: c.publishedAt, imageUrl: c.imageUrl || null,
    summary: String(e.summary ?? '').trim(), context: String(e.context ?? '').trim(),
    whyItMatters: String(e.whyItMatters ?? '').trim(), limitation: String(e.limitation ?? '').trim(),
    quickAction: String(e.quickAction ?? '').trim(), quickHack: String(e.quickHack ?? '').trim() });
}
return [{ json: { outputLanguage: framing.outputLanguage, digestTitle: framing.digestTitle, overview: framing.overview, intro: framing.intro, stories } }];
